CREATE MATERIALIZED VIEW non_leaf_1381 AS
SELECT pi.id AS pi_id, pi.person_id AS pi_person_id, pi.info_type_id AS pi_info_type_id, pi.info AS pi_info, pi.note AS pi_note, n.id AS n_id, n.name AS n_name, n.imdb_index AS n_imdb_index, n.imdb_id AS n_imdb_id, n.gender AS n_gender, n.name_pcode_cf AS n_name_pcode_cf, n.name_pcode_nf AS n_name_pcode_nf, n.surname_pcode AS n_surname_pcode, n.md5sum AS n_md5sum, ci.id AS ci_id, ci.person_id AS ci_person_id, ci.movie_id AS ci_movie_id, ci.person_role_id AS ci_person_role_id, ci.note AS ci_note, ci.nr_order AS ci_nr_order, ci.role_id AS ci_role_id, cn.id AS cn_id, cn.name AS cn_name, cn.country_code AS cn_country_code, cn.imdb_id AS cn_imdb_id, cn.name_pcode_nf AS cn_name_pcode_nf, cn.md5sum AS cn_md5sum, mc.id AS mc_id, mc.movie_id AS mc_movie_id, mc.company_id AS mc_company_id, mc.company_type_id AS mc_company_type_id, mc.note AS mc_note, mi1.id AS mi1_id, mi1.movie_id AS mi1_movie_id, mi1.info_type_id AS mi1_info_type_id, mi1.info AS mi1_info, mi1.note AS mi1_note, t.id AS t_id, t.title AS t_title, t.imdb_index AS t_imdb_index, t.kind_id AS t_kind_id, t.production_year AS t_production_year, t.imdb_id AS t_imdb_id, t.phonetic_code AS t_phonetic_code, t.episode_of_id AS t_episode_of_id, t.season_nr AS t_season_nr, t.episode_nr AS t_episode_nr, t.series_years AS t_series_years, t.md5sum AS t_md5sum, kt.id AS kt_id, kt.kind AS kt_kind, rt.id AS rt_id, rt.role AS rt_role, ct.id AS ct_id, ct.kind AS ct_kind, it2.id AS it2_id, it2.info AS it2_info, it1.id AS it1_id, it1.info AS it1_info
FROM person_info AS pi, name AS n, cast_info AS ci, company_name AS cn, movie_companies AS mc, movie_info AS mi1, title AS t, kind_type AS kt, role_type AS rt, company_type AS ct, info_type AS it2, info_type AS it1
WHERE pi.person_id = ci.person_id AND pi.info ~~* '%20%' AND pi.info_type_id = 23 AND n.id = ci.person_id AND ci.role_id = rt.id AND ci.movie_id = t.id AND cn.id = mc.company_id AND mc.movie_id = t.id AND mi1.movie_id = t.id AND mi1.info ~~* '%ca%' AND mi1.info_type_id = 8 AND t.kind_id = kt.id AND t.production_year <= 1990 AND t.production_year >= 1945 AND kt.kind IN ('episode', 'movie', 'tv mini series', 'tv movie', 'tv series', 'video game') AND rt.role IN ('actor', 'cinematographer', 'costume designer', 'editor', 'guest', 'miscellaneous crew', 'producer', 'production designer', 'writer') AND ct.id = mc.company_type_id AND it2.id = 23 AND it1.id = 8;